INSERT INTO curated_plant_content_second(product_code,expected_name,latin,short_text,full_text,care_text,light,watering) VALUES
  (575,'Антуриум','Anthurium','Цветущий антуриум с глянцевыми листьями и соцветием из покрывала и початка.','У антуриума яркое покрывало окружает початок с мелкими цветками. Он подходит для тёплого светлого места без прямых полуденных лучей; окраска и размер соцветий зависят от конкретного сорта.','Поставьте в яркий рассеянный свет. Поливайте, когда верхний слой субстрата начинает подсыхать, и сливайте лишнюю воду. Держите в тепле, вдали от холодных сквозняков; для корней нужен рыхлый дренированный субстрат.','diffused','moderate'),
  (33,'Антуриум','Anthurium','Цветущий антуриум с глянцевыми листьями и соцветием из покрывала и початка.','У антуриума яркое покрывало окружает початок с мелкими цветками. Он подходит для тёплого светлого места без прямых полуденных лучей; окраска и размер соцветий зависят от конкретного сорта.','Поставьте в яркий рассеянный свет. Поливайте, когда верхний слой субстрата начинает подсыхать, и сливайте лишнюю воду. Держите в тепле, вдали от холодных сквозняков; для корней нужен рыхлый дренированный субстрат.','diffused','moderate'),
